package ledger

// This file implements the ledger exercise: a refactoring of the original
// FormatLedger implementation.
//
// Refactoring log:
//  1. Extracted the supported locales and currencies into lookup tables
//     (locales, currencies) so validation is a simple map lookup.
//  2. Replaced the hand-rolled selection sort with sort.Slice over a copy
//     of the input, sorting by date, then description, then change.
//  3. Replaced the goroutine/channel fan-out with a simple sequential loop;
//     the goroutines added no value and made the code hard to follow.
//  4. Extracted the header, date, description, and amount formatting into
//     small helpers (header, formatDate, truncateDescription, formatAmount).
//  5. Replaced the manual date slicing with time.Parse, which also validates
//     the date instead of only checking separator positions.
//  6. Validated currency and locale up front so errors are returned before
//     any formatting work happens.

import (
	"errors"
	"sort"
	"strconv"
	"strings"
	"time"
	"unicode/utf8"
)

// Entry represents a single ledger entry.
type Entry struct {
	Date        string // "Y-m-d"
	Description string
	Change      int // in cents
}

var (
	errInvalidCurrency = errors.New("invalid currency")
	errInvalidLocale   = errors.New("invalid locale")
	errInvalidDate     = errors.New("invalid date")
)

const (
	dateColumnWidth      = 10
	descriptionColumnWidth = 25
	changeColumnWidth    = 13
)

// localeInfo holds the formatting rules for a supported locale.
type localeInfo struct {
	dateFormat     string // Go time layout for the output date
	decimalSep     string
	thousandsSep   string
	headers        [3]string
	formatAmount   func(symbol, number string, negative bool) string
}

var locales = map[string]localeInfo{
	"en-US": {
		dateFormat:   "01/02/2006",
		decimalSep:   ".",
		thousandsSep: ",",
		headers:      [3]string{"Date", "Description", "Change"},
		formatAmount: func(symbol, number string, negative bool) string {
			if negative {
				return "(" + symbol + number + ")"
			}
			return symbol + number + " "
		},
	},
	"nl-NL": {
		dateFormat:   "02-01-2006",
		decimalSep:   ",",
		thousandsSep: ".",
		headers:      [3]string{"Datum", "Omschrijving", "Verandering"},
		formatAmount: func(symbol, number string, negative bool) string {
			if negative {
				return symbol + " " + number + "-"
			}
			return symbol + " " + number + " "
		},
	},
}

var currencies = map[string]string{
	"USD": "$",
	"EUR": "€",
}

// FormatLedger returns a formatted ledger for the given entries, or an error
// if the currency, locale, or any entry date is invalid. The input slice is
// not modified.
func FormatLedger(currency string, locale string, entries []Entry) (string, error) {
	symbol, ok := currencies[currency]
	if !ok {
		return "", errInvalidCurrency
	}
	loc, ok := locales[locale]
	if !ok {
		return "", errInvalidLocale
	}

	sorted := make([]Entry, len(entries))
	copy(sorted, entries)
	sort.Slice(sorted, func(i, j int) bool {
		if sorted[i].Date != sorted[j].Date {
			return sorted[i].Date < sorted[j].Date
		}
		if sorted[i].Description != sorted[j].Description {
			return sorted[i].Description < sorted[j].Description
		}
		return sorted[i].Change < sorted[j].Change
	})

	var b strings.Builder
	b.WriteString(header(loc))
	for _, entry := range sorted {
		line, err := formatEntry(entry, symbol, loc)
		if err != nil {
			return "", err
		}
		b.WriteString(line)
	}
	return b.String(), nil
}

// header renders the column header line for the given locale.
func header(loc localeInfo) string {
	return pad(loc.headers[0], dateColumnWidth) + " | " +
		pad(loc.headers[1], descriptionColumnWidth) + " | " +
		loc.headers[2] + "\n"
}

// formatEntry renders a single ledger line, or an error if the date is invalid.
func formatEntry(entry Entry, symbol string, loc localeInfo) (string, error) {
	date, err := formatDate(entry.Date, loc.dateFormat)
	if err != nil {
		return "", err
	}
	amount := formatAmount(entry.Change, symbol, loc)
	return date + " | " +
		truncateDescription(entry.Description) + " | " +
		rightPad(amount, changeColumnWidth) + "\n"
}

// formatDate parses a "Y-m-d" date and re-renders it using the locale's layout.
func formatDate(date, layout string) (string, error) {
	t, err := time.Parse("2006-01-02", date)
	if err != nil {
		return "", errInvalidDate
	}
	return t.Format(layout), nil
}

// truncateDescription fits a description into the description column,
// truncating overlong values with an ellipsis.
func truncateDescription(desc string) string {
	if len(desc) > descriptionColumnWidth {
		return desc[:descriptionColumnWidth-3] + "..."
	}
	return pad(desc, descriptionColumnWidth)
}

// formatAmount renders a change in cents as a locale-formatted amount,
// e.g. "$1,234.56" or "€ 1.234,56".
func formatAmount(cents int, symbol string, loc localeInfo) string {
	negative := cents < 0
	if negative {
		cents = -cents
	}
	centsStr := padCents(strconv.Itoa(cents))
	number := groupThousands(centsStr[:len(centsStr)-2], loc.thousandsSep) +
		loc.decimalSep + centsStr[len(centsStr)-2:]
	return loc.formatAmount(symbol, number, negative)
}

// padCents left-pads a cents value with zeros so it always has at least
// three digits (one whole unit plus two decimal places).
func padCents(s string) string {
	switch len(s) {
	case 1:
		return "00" + s
	case 2:
		return "0" + s
	}
	return s
}

// groupThousands inserts the thousands separator into a digit string.
func groupThousands(digits, sep string) string {
	var out string
	for len(digits) > 3 {
		out = sep + digits[len(digits)-3:] + out
		digits = digits[:len(digits)-3]
	}
	return digits + out
}

// pad right-pads s with spaces up to width bytes.
func pad(s string, width int) string {
	return s + strings.Repeat(" ", width-len(s))
}

// rightPad right-pads s with leading spaces up to width runes.
func rightPad(s string, width int) string {
	return strings.Repeat(" ", width-utf8.RuneCountInString(s)) + s
}
